// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "../bridge";

export interface NursingAssessmentOut {
  admission_id: number;
  admitted_at: string | null;
  nutrition_screenings: NutritionScreeningOut[];
  latest_risk: "Low" | "Medium" | "High" | null;
  /** Not screened within nutrition_screening_hours of admission */
  screening_overdue: boolean;
  care_plan: NursingCarePlanOut | null;
  /** No care plan within nursing_care_plan_hours of admission */
  care_plan_overdue: boolean;
}

/** A nutrition screening (MSDS CQI 99 c): the three scores of the Malnutrition Universal Screening Tool. */
export interface NutritionScreeningOut {
  screening_id: number;
  screened_at: string;
  weight_kg: number | null;
  height_cm: number | null;
  bmi_score: number;
  weight_loss_score: number;
  acute_disease_score: number;
  total_score: number;
  risk: "Low" | "Medium" | "High";
  plan: string | null;
  author_stamp: AuthorStampOut;
}

/** The author stamp of a clinical entry (MSDS IMS 147), as the author's staff record stood when they signed it (SQL hms_author_stamp / hms_employee_stamp, migration 0013 [STP]). Show it under the entry on screen and print `text` under it on paper. */
export interface AuthorStampOut {
  employee_id: number | null;
  user_id: number | null;
  name: string;
  /** Designation and specialty, e.g. "Medical Officer, General Medicine" */
  designation: string | null;
  /** Council registration, e.g. "PMDC 12345-P" or "PNC 67890" */
  registration: string | null;
  /** When the entry was signed, reported or verified */
  at: string;
  /** The printed line: name, designation, registration, date and time */
  text: string;
}

/** The nursing care plan (MSDS CQI 99 d); every version is kept. */
export interface NursingCarePlanOut {
  care_plan_id: number;
  problems: string;
  goals: string;
  interventions: string;
  evaluation: string | null;
  written_at: string;
  updated_at: string;
  /** Of the last update */
  author_stamp: AuthorStampOut;
  row_version: number;
}

export interface NutritionScreeningIn {
  weight_kg?: number | null;
  height_cm?: number | null;
  /** Body mass index: over 20 = 0, 18.5-20 = 1, under 18.5 = 2 */
  bmi_score: number;
  /** Unplanned weight loss in 3-6 months: under 5 % = 0, 5-10 % = 1, over 10 % = 2 */
  weight_loss_score: number;
  /** Acutely ill with no intake for over 5 days: 2, else 0 */
  acute_disease_score: number;
  /** Needed for a medium or high risk */
  plan?: string | null;
}

export interface NursingCarePlanIn {
  /** The nursing diagnoses */
  problems: string;
  goals: string;
  interventions: string;
  /** How the patient responded, at each review */
  evaluation?: string | null;
  /** Optimistic concurrency: the row_version you loaded */
  expected_version?: number | null;
}

/** The nursing assessment: nutrition screenings and the nursing care plan — GET /api/v1/admissions/{admission_id}/nursing-assessment (who may call: holders of ipd.flowsheet.view or ipd.nursing_assessment.record). */
export function nursingAssessmentView(admission_id: number): Promise<NursingAssessmentOut> {
  return api<NursingAssessmentOut>("GET", `/admissions/${admission_id}/nursing-assessment`, undefined);
}

/** Screen an inpatient for nutrition — POST /api/v1/admissions/{admission_id}/nutrition-screenings (who may call: holders of ipd.nursing_assessment.record). */
export function nutritionScreening(admission_id: number, body: NutritionScreeningIn): Promise<NursingAssessmentOut> {
  return api<NursingAssessmentOut>("POST", `/admissions/${admission_id}/nutrition-screenings`, body, { idempotent: true });
}

/** Write or update the nursing care plan — PUT /api/v1/admissions/{admission_id}/nursing-care-plan (who may call: holders of ipd.nursing_assessment.record). */
export function nursingCarePlan(admission_id: number, body: NursingCarePlanIn): Promise<NursingAssessmentOut> {
  return api<NursingAssessmentOut>("PUT", `/admissions/${admission_id}/nursing-care-plan`, body);
}
